import { Link, useParams } from "react-router-dom";
import policiesJson from "../data/policies.json";
import { Seo } from "../components/Seo";
import { NotFoundPage } from "./NotFoundPage";
import { getCmsPage } from "../lib/site";
import { PageSections } from "../components/sections/PageSections";

type Block = { type: "paragraph"; html: string };
// SAFETY: policies.json is generated by scripts/extract-content.mjs with exactly this shape.
const POLICIES = policiesJson as unknown as Record<
    string,
    { title: string; blocks: Block[] }
>;

// Policy pages built from the current captured copies (docs/reference/captures/policy_*.html).
// Policy text matches the reconstruction's actual storage/submission behavior (cart in browser,
// Zalo handoff, COD/bank transfer) — acceptance requirement from pages/05.
function PolicyArticle({ title, blocks }: { title: string; blocks: Block[] }) {
    return (
        <main id="main">
            <section className="c-hero">
                <div className="wrap">
                    <h1>{title}</h1>
                </div>
            </section>
            <div className="ivory">
                <div className="wrap txt-page">
                    {blocks.map((b, i) => (
                        <p key={i}>{renderBlocks(b.html)}</p>
                    ))}
                </div>
            </div>
        </main>
    );
}

// The captured paragraph content is plain text plus a single link marker (@@LINK|href|label@@).
function renderBlocks(html: string) {
    const parts = html.split(/@@LINK\|([^|]+)\|([^@]+)@@/g);
    const out: React.ReactNode[] = [];
    for (let i = 0; i < parts.length; i += 3) {
        out.push(parts[i]);
        if (i + 2 < parts.length) {
            const href = "/" + parts[i + 1].replace(/^\//, ""); // canonical route path
            out.push(
                <Link key={i} className="link" to={href}>
                    {parts[i + 2]}
                </Link>,
            );
        }
    }
    return out;
}

export function PolicyPage() {
    const { slug = "" } = useParams();
    // A published CMS page wins over the bundled policy copy for the same slug.
    const cms = getCmsPage(slug);
    if (cms) {
        return (
            <main id="main">
                <Seo title={cms.seo?.title ?? cms.title} description={cms.seo?.description ?? ""} />
                <section className="c-hero">
                    <div className="wrap">
                        <h1>{cms.title}</h1>
                    </div>
                </section>
                <PageSections sections={cms.sections} />
            </main>
        );
    }
    const policy = POLICIES[slug];
    if (!policy)
        return <NotFoundPage note="Trang chính sách này không tồn tại." />;
    return (
        <>
            <Seo
                title={`${policy.title} | Lagom Flower`}
                description={`${policy.title} – Lagom Flower.`}
                path={`/pages/${slug}/`}
            />
            <PolicyArticle title={policy.title} blocks={policy.blocks} />
        </>
    );
}
